text:
.hub-body {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  place-self: center;
  gap: var(--hub-body-elements-column-gap);
  inline-size: 100%;
  max-inline-size: var(--hub-width);
  text-align: start;
  margin-inline: 0;

  &.flex-direction-row {
    flex-direction: row;
  }

  &.auto-config-body {
    max-inline-size: 750px;
  }
